INSERT INTO lessons (id, ordinal, icon, title_en, title_ar, description_en, description_ar) VALUES (1, 0, $q$&#128279;$q$, $q$Linked List Basics$q$, $q$أساسيات الـ Linked List$q$, $q$Head, Node, Data, Next, and NULL &mdash; the core building blocks, plus how Insert and Delete work without moving anything in memory.$q$, $q$Head و Node و Data و Next و NULL &mdash; أساسيات الفكرة، وإزاي عمليات الإضافة والحذف بتتم من غير ما ننقل أي حاجة في الذاكرة.$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 0, $q$Data Structures &amp; Algorithms$q$, $q$هياكل البيانات والخوارزميات$q$, $q$Linked List$q$, $q$Linked List$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex flex-col items-center mr-2">
            <div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div>
            <div class="w-0 h-4"></div>
        </div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div>
        <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div>
        <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div>
        <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
        <div class="w-9 h-9 text-xs rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div>
    </div>
    </div>$q$, $q$<p>Look at the picture above &mdash; that <strong>is</strong> the entire Linked List.</p>
         <p>We're going to explain it piece by piece, as if we're seeing it for the very first time. Nothing will be skipped &mdash; just slowed down.</p>$q$, $q$<p>بص على الرسمة اللي فوق &mdash; دي هي الـ Linked List <strong>كلها</strong>.</p>
         <p>هنفهمها واحدة واحدة، كأننا أول مرة نشوفها. مفيش حاجة هتتشال، بس هنبطّئ الشرح شوية.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 1, $q$The pieces$q$, $q$الأجزاء$q$, $q$How many parts do we have?$q$, $q$عندنا كام حاجة؟$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex flex-col items-center mr-2">
            <div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div>
            <div class="w-0 h-4"></div>
        </div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div>
        <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div>
        <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div>
        <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
        <div class="w-9 h-9 text-xs rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div>
    </div>
    </div>$q$, $q$<p>We have 4 things on screen:</p>
         <ul class="list-disc list-inside space-y-1 my-3">
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code></li>
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node A</code></li>
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node B</code></li>
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C</code></li>
         </ul>
         <p>But here's the catch: <strong>Head is not a Node.</strong> It's just a pointer.</p>$q$, $q$<p>عندنا ٤ حاجات على الشاشة:</p>
         <ul class="list-disc list-inside space-y-1 my-3">
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code></li>
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node A</code></li>
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node B</code></li>
            <li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C</code></li>
         </ul>
         <p>لكن الحقيقة: <strong>الـ Head مش Node.</strong> هو مجرد Pointer.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 2, $q$First up$q$, $q$أول حاجة$q$, $q$Head$q$, $q$Head$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div></div>
    </div><div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div> <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div></div>
    </div>$q$, $q$<p><code class="bg-brand-light text-brand-dark px-2 py-1 rounded-md text-sm font-mono border border-brand-purple/20">Head</code> is a variable. It does not store data.</p>
         <p>It stores the <strong>address</strong> of the first node. So instead of holding a number like <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = 10</code>, it holds an address, for example <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = 0x1000</code> &mdash; the address of the first node.</p>
         <p>In other words, Head is saying: <em>"the first element lives over there."</em></p>$q$, $q$<p><code class="bg-brand-light text-brand-dark px-2 py-1 rounded-md text-sm font-mono border border-brand-purple/20">Head</code> عبارة عن متغير. مش بيخزن بيانات.</p>
         <p>هو بيخزن <strong>عنوان</strong> أول Node. يعني بدل ما يكون جواه رقم زي <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = 10</code>، هيكون جواه Address، مثلًا <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = 0x1000</code> &mdash; عنوان أول Node.</p>
         <p>يعني الـ Head بيقول: <em>"أول عنصر موجود هناك."</em></p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 3, $q$Why it matters$q$, $q$ليه محتاجينه$q$, $q$Why do we need Head?$q$, $q$ليه محتاجين Head؟$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        <div class="absolute -top-3 left-4 bg-white border border-gray-200 px-3 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Head is lost</div>
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="w-10 h-10 rounded-full border-2 border-dashed border-rose-400 flex items-center justify-center text-rose-500 font-bold text-xl flex-shrink-0">?</div>
        <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-gray-300 bg-gray-100 text-gray-400 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div>
        <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-gray-300 bg-gray-100 text-gray-400 flex items-center justify-center font-bold node-3d flex-shrink-0">B</div>
        <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-gray-300 bg-gray-100 text-gray-400 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div>
    </div>
    </div>$q$, $q$<p>Because the entire Linked List starts from it.</p>
         <p>If Head is lost, we no longer know how to reach <em>any</em> node &mdash; the whole list is gone, even though every node still technically exists in memory.</p>$q$, $q$<p>لأن كل الـ Linked List بتبدأ منه.</p>
         <p>لو ضاع الـ Head... مبقيناش عارفين نوصل لأي Node. يعني القائمة كلها ضاعت، حتى لو كل Node لسه موجودة في الذاكرة.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 4, $q$Second up$q$, $q$ثاني حاجة$q$, $q$Node$q$, $q$Node$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex rounded-2xl border-[3px] border-brand-purple overflow-hidden node-3d">
            <div class="w-16 h-16 sm:w-20 sm:h-20 bg-brand-light text-brand-dark flex items-center justify-center font-bold text-sm border-r-2 border-brand-purple">Data</div>
            <div class="w-16 h-16 sm:w-20 sm:h-20 bg-white text-brand-dark flex items-center justify-center font-bold text-sm">Next</div>
        </div>
    </div>
    </div>$q$, $q$<p>Every rectangle in the diagram is called a <strong>Node</strong>.</p>
         <p>Each Node has exactly two things inside it: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data</code> and <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code>.</p>$q$, $q$<p>كل مستطيل في الرسمة اسمه <strong>Node</strong>.</p>
         <p>كل Node فيها حاجتين بالظبط: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data</code> و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 5, $q$Inside the node$q$, $q$جوه الـ Node$q$, $q$Data$q$, $q$Data$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex flex-wrap gap-3 justify-center">
            <div class="px-4 py-2 rounded-lg bg-white border-2 border-brand-purple/30 font-mono text-sm text-brand-dark shadow-sm">5</div>
            <div class="px-4 py-2 rounded-lg bg-white border-2 border-brand-purple/30 font-mono text-sm text-brand-dark shadow-sm">"Ahmed"</div>
            <div class="px-4 py-2 rounded-lg bg-white border-2 border-brand-purple/30 font-mono text-sm text-brand-dark shadow-sm">Student</div>
            <div class="px-4 py-2 rounded-lg bg-white border-2 border-brand-purple/30 font-mono text-sm text-brand-dark shadow-sm">Car</div>
        </div>
    </div>
    </div>$q$, $q$<p>This is the actual data. It could be <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">5</code>, or <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">"Ahmed"</code>, or a <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Student</code> object, a <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Car</code> object, or really any object at all.</p>
         <p>This part is simply the value itself.</p>$q$, $q$<p>دي البيانات. ممكن تكون <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">5</code>، أو <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">"Ahmed"</code>، أو <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Student</code>، أو <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Car</code>، أو أي Object تاني.</p>
         <p>يعني الجزء ده هو القيمة نفسها.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 6, $q$Inside the node$q$, $q$جوه الـ Node$q$, $q$Next$q$, $q$Next$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex rounded-2xl border-[3px] border-brand-purple overflow-hidden node-3d flex-shrink-0">
            <div class="w-14 h-14 sm:w-16 sm:h-16 bg-brand-light text-brand-dark flex items-center justify-center font-bold text-sm border-r-2 border-brand-purple">5</div>
            <div class="w-14 h-14 sm:w-16 sm:h-16 bg-white text-brand-dark flex items-center justify-center font-mono font-bold text-xs">0x500</div>
        </div>
        <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div>
        <div class="w-14 h-14 sm:w-16 sm:h-16 rounded-2xl border-[3px] border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold text-sm node-3d flex-shrink-0">Node</div>
    </div>
    </div>$q$, $q$<p>This is the most important part.</p>
         <p><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code> does not store a value. It stores the <strong>address of another node</strong> &mdash; a pointer.</p>
         <p>For example: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data = 5</code>, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next = 0x500</code>. That means: go to address <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">0x500</code>, and you'll find the next node there.</p>$q$, $q$<p>وده أهم جزء.</p>
         <p><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code> مش بيخزن قيمة. بيخزن <strong>عنوان Node تانية</strong> &mdash; يعني Pointer.</p>
         <p>مثلًا: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data = 5</code>، <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next = 0x500</code>. ده معناه: روح للعنوان <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">0x500</code>، هتلاقي الـ Node اللي بعدها.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 7, $q$Putting it together$q$, $q$الخلاصة$q$, $q$One Node = Data + Next$q$, $q$الـ Node = Data + Next$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex items-center gap-4">
            <div class="flex rounded-2xl border-[3px] border-brand-purple overflow-hidden node-3d">
                <div class="w-16 h-16 bg-brand-light text-brand-dark flex items-center justify-center font-bold text-sm border-r-2 border-brand-purple">Data</div>
                <div class="w-16 h-16 bg-white text-brand-dark flex items-center justify-center font-bold text-sm">Next</div>
            </div>
        </div>
    </div>
    </div>$q$, $q$<p>So a single Node is simply:</p>
         <div class="bg-gray-900 text-white rounded-xl p-5 font-mono text-sm my-3">
            Node<br>&nbsp;&nbsp;Data<br>&nbsp;&nbsp;Next
         </div>
         <p>In plain words: <strong>a value, plus the address of whatever comes next.</strong></p>$q$, $q$<p>يبقى الـ Node الواحدة عبارة عن:</p>
         <div class="bg-gray-900 text-white rounded-xl p-5 font-mono text-sm my-3" dir="ltr">
            Node<br>&nbsp;&nbsp;Data<br>&nbsp;&nbsp;Next
         </div>
         <p>يعني: <strong>قيمة + عنوان اللي بعدها.</strong></p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 8, $q$Example$q$, $q$مثال$q$, $q$Node A$q$, $q$Node A$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div> <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div> <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div></div>
    </div><div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="text-sm font-mono text-gray-600">Data = A <span class="text-gray-400">(e.g. 10)</span></div></div>
    </div><div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="flex items-center gap-3 font-mono text-sm text-gray-600">Next = <span class="text-brand-dark font-bold">0x700</span> <span class="text-gray-400">&rarr; address of Node B</span></div></div>
    </div>$q$, $q$<p>Node A holds <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data = A</code> (say, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">10</code>).</p>
         <p>Its <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code> does not literally say "Node B". It stores Node B's <strong>address</strong>, for example <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">0x700</code>.</p>$q$, $q$<p>Node A فيها <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data = A</code> (مثلًا <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">10</code>).</p>
         <p>وكمان <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code>. الـ Next مش بيقول "Node B"، هو بيخزن <strong>عنوان</strong> Node B، مثلًا <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">0x700</code>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 9, $q$Example$q$, $q$مثال$q$, $q$Node B$q$, $q$Node B$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div> <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div> <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div></div>
    </div><div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="text-sm font-mono text-gray-600">Data = 20</div></div>
    </div>$q$, $q$<p>Same idea. Node B holds <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data = 20</code>.</p>
         <p>Its <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code> points to Node C.</p>$q$, $q$<p>نفس الفكرة. Node B فيها <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data = 20</code>.</p>
         <p>وبعدين <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code> يشاور على Node C.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 10, $q$Example$q$, $q$مثال$q$, $q$Node C$q$, $q$Node C$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div> <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div> <div class="w-12 h-12 text-sm rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div></div>
    </div>$q$, $q$<p>Node C has its <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data</code>, then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code> &mdash; but nothing comes after it.</p>
         <p>So: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next = NULL</code>.</p>$q$, $q$<p>فيها Data. ثم Next. لكن مفيش بعدها حاجة.</p>
         <p>يبقى <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next = NULL</code>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 11, $q$A special value$q$, $q$قيمة خاصة$q$, $q$What does NULL mean?$q$, $q$يعني إيه NULL؟$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="w-16 h-16 text-2xl rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div></div>
    </div>$q$, $q$<p><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code> means "no address." Nothing. It means the list has ended.</p>
         <p>When the program reaches <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next = NULL</code>, it knows: that's it, there are no more nodes.</p>$q$, $q$<p>NULL معناها "مفيش عنوان". يعني Nothing. يعني انتهت القائمة.</p>
         <p>لما البرنامج يوصل لـ <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next = NULL</code>، هيعرف إن خلاص، مفيش Nodes بعدها.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 12, $q$A safety rule$q$, $q$قاعدة أمان$q$, $q$Why must the last node be NULL?$q$, $q$ليه آخر Node لازم تبقى NULL؟$q$, $q$<div class="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
        <div class="bg-emerald-50 border border-emerald-200 rounded-xl p-5 text-center">
            <div class="flex justify-center mb-3"><div class="w-12 h-12 text-sm rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div></div>
            <div class="text-xs font-bold text-emerald-600 uppercase tracking-wider">Next = NULL &mdash; safe stop</div>
        </div>
        <div class="bg-rose-50 border border-rose-200 rounded-xl p-5 text-center">
            <div class="text-2xl mb-3">&#9888;&#65039;</div>
            <div class="text-xs font-bold text-rose-600 uppercase tracking-wider font-mono">Next = 0x123 &mdash; crash / garbage</div>
        </div>
    </div>$q$, $q$<p>Imagine it wasn't NULL, and instead held a random leftover address, like <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next = 0x123</code>.</p>
         <p>The program would try to follow that address. It might find garbage data, or the program might crash.</p>
         <p>That's why the last node has to explicitly say <strong>"I am the last one"</strong> &mdash; and that's exactly what <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code> does.</p>$q$, $q$<p>تخيل إنها مش NULL، وكان جواها أي Address عشوائي، زي <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next = 0x123</code>.</p>
         <p>البرنامج هيحاول يروح للعنوان ده. ممكن يلاقي Garbage، أو يعمل Crash.</p>
         <p>عشان كده لازم آخر Node تقول <strong>"أنا آخر واحدة"</strong> &mdash; وده بالظبط اللي بتعمله <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 13, $q$Walking the list$q$, $q$إزاي نمشي جواها$q$, $q$How do we traverse a Linked List?$q$, $q$إزاي نمشي جوه Linked List؟$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex flex-col items-center mr-1"><div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div><div class="w-4 h-4"></div></div>
        <div class="flex flex-col items-center">
            <span class="text-[10px] font-bold text-gray-400 mb-1">1</span>
            <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div>
        </div>
        <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div>
        <div class="flex flex-col items-center">
            <span class="text-[10px] font-bold text-gray-400 mb-1">2</span>
            <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div>
        </div>
        <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div>
        <div class="flex flex-col items-center">
            <span class="text-[10px] font-bold text-gray-400 mb-1">3</span>
            <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div>
        </div>
        <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
        <div class="flex flex-col items-center">
            <span class="text-[10px] font-bold text-gray-400 mb-1">4 &mdash; stop</span>
            <div class="w-9 h-9 text-xs rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div>
        </div>
    </div>
    </div>$q$, $q$<p>We start at <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code>, which points to Node A. Then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node A.Next</code> takes us to Node B. Then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node B.Next</code> takes us to Node C. Then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next</code> is <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code>, so we stop.</p>
         <p>In other words: the whole movement is about <strong>following pointers</strong>, not jumping between neighboring memory slots.</p>$q$, $q$<p>بنبدأ من <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code>، بيشاور على Node A. بعدين <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node A.Next</code> يوصلنا لـ Node B. بعدين <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node B.Next</code> يوصلنا لـ Node C. بعدين <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next</code> يبقى <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code>، فنقف.</p>
         <p>يعني الحركة كلها عبارة عن اتباع مؤشرات (Pointers)، مش بالقفز على عناصر متجاورة في الذاكرة.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 14, $q$Under the hood$q$, $q$تحت السطح$q$, $q$A memory address example$q$, $q$مثال بالأرقام$q$, $q$
        <div class="bg-gray-50 border border-gray-200 rounded-xl p-5 mb-4 overflow-x-auto">
            <table class="w-full text-sm font-mono min-w-[280px]">
                <thead><tr class="text-gray-400 text-xs uppercase"><th class="text-left pb-2">Address</th><th class="text-left pb-2">Data</th></tr></thead>
                <tbody class="text-gray-700">
                    <tr class="border-t border-gray-200"><td class="py-2">1000</td><td class="py-2 font-bold text-orange-600">Node A</td></tr>
                    <tr class="border-t border-gray-200"><td class="py-2">5000</td><td class="py-2 font-bold text-brand-dark">Node B</td></tr>
                    <tr class="border-t border-gray-200"><td class="py-2">2000</td><td class="py-2 font-bold text-teal-600">Node C</td></tr>
                </tbody>
            </table>
        </div>
        <div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        <div class="absolute -top-3 left-4 bg-white border border-gray-200 px-3 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Logical order via Next, despite scattered addresses</div>
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
            <div class="flex flex-col items-center"><span class="text-[10px] text-gray-400 font-mono mb-1">1000</span><div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div></div>
            <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div>
            <div class="flex flex-col items-center"><span class="text-[10px] text-gray-400 font-mono mb-1">5000</span><div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div></div>
            <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div>
            <div class="flex flex-col items-center"><span class="text-[10px] text-gray-400 font-mono mb-1">2000</span><div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div></div>
            <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
            <div class="w-9 h-9 text-xs rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div>
        </div>
    </div>
    $q$, $q$<p>Suppose memory looks like this: Node A is at <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">1000</code>, Node B at <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">5000</code>, Node C at <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">2000</code>.</p>
         <p>Notice: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">1000, 5000, 2000</code> are <strong>not</strong> next to each other. Yet <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node A.Next = 5000</code>, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node B.Next = 2000</code>, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next = NULL</code>.</p>
         <p>So the program can still walk <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">1000 &rarr; 5000 &rarr; 2000 &rarr; NULL</code>, even though the nodes live in completely different, scattered places in memory. This is exactly what <strong>"Independent, Nonconsecutive memory stores"</strong> means: each node exists on its own, and what links them together is the value of <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code> (the address) &mdash; not their physical position.</p>$q$, $q$<p>نفترض الذاكرة بالشكل ده: Node A في <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">1000</code>، Node B في <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">5000</code>، Node C في <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">2000</code>.</p>
         <p>لاحظ إن <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">1000, 5000, 2000</code> مش ورا بعض. ومع ذلك <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node A.Next = 5000</code>، <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node B.Next = 2000</code>، <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Node C.Next = NULL</code>.</p>
         <p>يبقى البرنامج يقدر يمشي <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">1000 &larr; 5000 &larr; 2000 &larr; NULL</code> رغم إن الأماكن متفرقة تمامًا في الذاكرة. وده سبب الجملة: <strong>"Independent Nonconsecutive memory stores"</strong> &mdash; يعني كل Node موجودة بشكل مستقل، ومش لازم تكون في أماكن متجاورة. اللي بيربطهم ببعض هو قيمة Next (العنوان)، مش مكانهم الفيزيائي.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 15, $q$Operation$q$, $q$عملية$q$, $q$Inserting a new node$q$, $q$لو حبينا نضيف Node جديدة$q$, $q$
        <div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        <div class="absolute -top-3 left-4 bg-white border border-gray-200 px-3 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Before</div>
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div> <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div> <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div></div>
    </div>
        <div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        <div class="absolute -top-3 left-4 bg-white border border-gray-200 px-3 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">After: insert X between A and B</div>
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div> <div class="w-8 sm:w-10 h-1 bg-rose-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-rose-400"></div></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-rose-400 bg-rose-50 text-rose-600 flex items-center justify-center font-bold node-3d flex-shrink-0">X</div> <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div> <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div></div>
    </div>
    $q$, $q$<p>Say we have <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; B &rarr; C</code> and we want to place <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">X</code> between A and B.</p>
         <p>We create a new node X, set <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">X.Next = B</code>, then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A.Next = X</code>.</p>
         <p>Now we have <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; X &rarr; B &rarr; C</code>. <strong>No node ever had to move.</strong></p>$q$, $q$<p>لو عندنا <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; B &rarr; C</code> وعايزين نحط <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">X</code> بين A و B.</p>
         <p>هنعمل Node جديدة X، نخلي <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">X.Next = B</code>، وبعدين <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A.Next = X</code>.</p>
         <p>فتبقى <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; X &rarr; B &rarr; C</code>. <strong>ولا احتجنا ننقل أي Node من مكانها.</strong></p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 16, $q$Operation$q$, $q$عملية$q$, $q$Deleting a node$q$, $q$ولو شلنا Node؟$q$, $q$
        <div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        <div class="absolute -top-3 left-4 bg-white border border-gray-200 px-3 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Before</div>
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div> <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div> <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div> <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div></div>
    </div>
        <div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        <div class="absolute -top-3 left-4 bg-white border border-gray-200 px-3 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">After: A points directly to C</div>
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
            <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div>
            <div class="flex flex-col items-center mx-1">
                <div class="w-8 sm:w-10 h-1 bg-gray-300 relative -mb-1"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-gray-300"></div></div>
                <span class="text-lg leading-none text-gray-300">&times;</span>
            </div>
            <div class="w-16 h-16 rounded-2xl border-[3px] border-dashed border-gray-300 bg-gray-50 text-gray-300 flex items-center justify-center font-bold text-xl flex-shrink-0 line-through">B</div>
            <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div>
            <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div>
        </div>
    </div>
    $q$, $q$<p>Say we have <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; B &rarr; C</code> and want to remove <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code>.</p>
         <p>Instead of <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A.Next</code> pointing to B, we make it point directly to C.</p>
         <p>Now we have <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; C</code>. Again &mdash; <strong>no node had to move.</strong></p>$q$, $q$<p>مثلًا <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; B &rarr; C</code> وهنشيل <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code>.</p>
         <p>بدل ما <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A.Next</code> يشاور على B، هيشاور مباشرة على C.</p>
         <p>فتبقى <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A &rarr; C</code>. وبرضه ولا نقلنا أي عنصر.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 17, $q$Recap$q$, $q$ملخص$q$, $q$Summary$q$, $q$ملخص الرسمة$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2">
        <div class="flex flex-col items-center mr-2">
            <div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div>
            <div class="w-0 h-4"></div>
        </div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">A</div>
        <div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">B</div>
        <div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div>
        <div class="w-14 h-14 text-lg rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">C</div>
        <div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div>
        <div class="w-9 h-9 text-xs rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div>
    </div>
    </div>$q$, $q$<ul class="list-disc list-inside space-y-2">
            <li><strong>Head</strong>: a pointer to the first node.</li>
            <li>Every <strong>Node</strong> has two parts: <strong>Data</strong> (the value) and <strong>Next</strong> (the address of the following node).</li>
            <li>The <strong>last node</strong> must have <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next = NULL</code>, so we know the list has ended.</li>
            <li>Nodes <strong>don't need to be next to each other</strong> in memory &mdash; they're linked purely through pointers.</li>
            <li>To reach any element, you must start at <strong>Head</strong> and walk node by node using <strong>Next</strong>.</li>
         </ul>$q$, $q$<ul class="list-disc list-inside space-y-2">
            <li><strong>Head</strong>: Pointer على أول Node.</li>
            <li>كل <strong>Node</strong> فيها جزئين: <strong>Data</strong> (القيمة) و <strong>Next</strong> (عنوان الـ Node اللي بعدها).</li>
            <li><strong>آخر Node</strong> لازم يكون <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next = NULL</code> عشان نعرف إن القائمة انتهت.</li>
            <li>الـ Nodes <strong>مش لازم تكون متجاورة في الذاكرة</strong>؛ الربط بينهم بيتم عن طريق الـ Pointers.</li>
            <li>للوصول لأي عنصر، لازم تبدأ من <strong>Head</strong> وتمشي Node بـ Node باستخدام <strong>Next</strong>.</li>
         </ul>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (1, 18, $q$What's next$q$, $q$الجزء الجاي$q$, $q$Linked List Operations$q$, $q$عمليات الـ Linked List$q$, $q$<div class="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-2">
        <div class="bg-brand-light border border-brand-purple/20 rounded-xl p-4 text-center">
            <div class="text-2xl mb-1">&#128269;</div>
            <div class="text-xs font-bold text-brand-dark">Traversal</div>
        </div>
        <div class="bg-brand-light border border-brand-purple/20 rounded-xl p-4 text-center">
            <div class="text-2xl mb-1">&#128270;</div>
            <div class="text-xs font-bold text-brand-dark">Find</div>
        </div>
        <div class="bg-brand-light border border-brand-purple/20 rounded-xl p-4 text-center">
            <div class="text-2xl mb-1">&#10133;</div>
            <div class="text-xs font-bold text-brand-dark">Insert</div>
        </div>
        <div class="bg-brand-light border border-brand-purple/20 rounded-xl p-4 text-center">
            <div class="text-2xl mb-1">&#10134;</div>
            <div class="text-xs font-bold text-brand-dark">Delete</div>
        </div>
    </div>$q$, $q$<p>In the next part, we'll cover the core Linked List operations &mdash; <strong>Traversal</strong>, <strong>Find</strong>, <strong>Insert</strong>, <strong>Delete</strong> &mdash; with step-by-step diagrams, understanding exactly what happens in memory for each one.</p>$q$, $q$<p>في الجزء اللي بعده هنبدأ نشرح عمليات الـ Linked List (<strong>Traversal</strong>، <strong>Find</strong>، <strong>Insert</strong>، <strong>Delete</strong>) برسومات خطوة بخطوة ونفهم كل عملية بتحصل في الذاكرة إزاي.</p>$q$);

INSERT INTO lessons (id, ordinal, icon, title_en, title_ar, description_en, description_ar) VALUES (2, 1, $q$&#128694;$q$, $q$Traversal$q$, $q$Traversal$q$, $q$How to walk through a linked list node by node using a current pointer &mdash; the operation every other one depends on.$q$, $q$إزاي تمشي جوه الـ Linked List Node بـ Node باستخدام current &mdash; العملية اللي كل حاجة تانية مبنية عليها.$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (2, 0, $q$Lesson 2 &middot; Core Operation$q$, $q$الدرس الثاني · أهم عملية$q$, $q$Traversal$q$, $q$Traversal (المشي داخل الـ Linked List)$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="flex flex-col items-center mr-1">
        <div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div>
        <div class="w-0 h-4"></div>
    </div><div class="flex flex-col items-center">
            <div class="h-6"></div>
            <div class="w-0 h-4"></div>
            <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">10</div>
        </div><div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div><div class="flex flex-col items-center">
            <div class="h-6"></div>
            <div class="w-0 h-4"></div>
            <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">20</div>
        </div><div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div><div class="flex flex-col items-center">
            <div class="h-6"></div>
            <div class="w-0 h-4"></div>
            <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">30</div>
        </div><div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div><div class="flex flex-col items-center">
        <div class="h-6"></div>
        <div class="w-0 h-4"></div>
        <div class="w-9 h-9 text-xs rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div>
    </div></div>
    </div>$q$, $q$<p>Now we start the most important part of Linked Lists: <strong>how do we walk through it (Traversal)?</strong></p>
         <p>Every other operation &mdash; Search, Delete, Insert &mdash; is built on top of this one.</p>
         <p>Suppose we have this list: the first node holds <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">10</code>, then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">20</code>, then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">30</code>, then <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code>.</p>$q$, $q$<p>ممتاز. دلوقتي هنبدأ أهم جزء في الـ Linked List، وهو <strong>إزاي نمشي فيها (Traversal)</strong>، لأن كل العمليات التانية (Search - Delete - Insert) مبنية عليه.</p>
         <p>نفترض عندنا الـ List دي: أول Node فيها <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">10</code>، بعدها <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">20</code>، بعدها <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">30</code>، بعدها <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (2, 1, $q$The problem$q$, $q$أول سؤال$q$, $q$There is no index$q$, $q$مفيش Index$q$, $q$<div class="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-2">
        <div class="bg-emerald-50 border border-emerald-200 rounded-xl p-5 text-center">
            <div class="font-mono text-lg text-emerald-700 mb-1">arr[2]</div>
            <div class="text-xs font-bold text-emerald-600 uppercase tracking-wider">Array &mdash; direct access &#10003;</div>
        </div>
        <div class="bg-rose-50 border border-rose-200 rounded-xl p-5 text-center">
            <div class="font-mono text-lg text-rose-400 mb-1 line-through">list[2]</div>
            <div class="text-xs font-bold text-rose-600 uppercase tracking-wider">Linked List &mdash; no index &#10007;</div>
        </div>
    </div>$q$, $q$<p>Say I ask you: <strong>give me the last element.</strong></p>
         <p>In an array, that's easy: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">arr[2]</code> and we're done.</p>
         <p>But here? There's no index. There's no <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">list[2]</code>.</p>
         <p>So what do we do? We have to walk through it <strong>one node at a time</strong>.</p>$q$, $q$<p>لو قلتلك: <strong>هاتلي آخر عنصر.</strong></p>
         <p>في Array الموضوع سهل: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">arr[2]</code>. خلصنا.</p>
         <p>لكن هنا؟ مفيش Index. مفيش <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">list[2]</code>.</p>
         <p>يبقى هنعمل إيه؟ لازم نمشي واحدة واحدة.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (2, 2, $q$Starting point$q$, $q$هنبدأ منين؟$q$, $q$Always from Head$q$, $q$دايماً من الـ Head$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
        <div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="flex flex-col items-center mr-1">
        <div class="relative flex flex-col items-center animate-bounce-subtle">
        <div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Head</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div>
    </div>
        <div class="w-0 h-4"></div>
    </div><div class="flex flex-col items-center">
            <div class="relative flex flex-col items-center animate-bounce-subtle" style="animation-delay:0.1s">
        <div class="bg-teal-500 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">current</div>
        <div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-teal-500 mt-0.5"></div>
    </div>
            <div class="w-0 h-4"></div>
            <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d flex-shrink-0">10</div>
        </div><div class="w-8 sm:w-10 h-1 bg-orange-400 relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-orange-400"></div></div><div class="flex flex-col items-center">
            <div class="h-6"></div>
            <div class="w-0 h-4"></div>
            <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">20</div>
        </div><div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div><div class="flex flex-col items-center">
            <div class="h-6"></div>
            <div class="w-0 h-4"></div>
            <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d flex-shrink-0">30</div>
        </div><div class="w-8 sm:w-10 h-0 border-t-2 border-dashed border-gray-300 flex-shrink-0"></div><div class="flex flex-col items-center">
        <div class="h-6"></div>
        <div class="w-0 h-4"></div>
        <div class="w-9 h-9 text-xs rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400 font-bold bg-white flex-shrink-0">∅</div>
    </div></div>
    </div><div class=" bg-[#1E1E2E] rounded-xl p-5 shadow-inner border border-gray-800 font-mono text-[13px] text-gray-300 leading-relaxed overflow-x-auto my-4" dir="ltr"><pre class="m-0"><code>current = Head;</code></pre></div>$q$, $q$<p>We always start from <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code>, because it's the only node whose location we actually know.</p>
         <p>So the first step is: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">current = Head</code>.</p>$q$, $q$<p>دايماً... من الـ Head. لأن Head هو الوحيد اللي نعرف مكانه.</p>
         <p>يعني أول خطوة: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">current = Head</code>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (2, 3, $q$Why a separate pointer?$q$, $q$ليه عملنا current؟$q$, $q$Head must stay put$q$, $q$ليه عملنا current؟$q$, $q$<div class="code-cpp bg-[#1E1E2E] rounded-xl p-5 shadow-inner border border-gray-800 font-mono text-[13px] text-gray-300 leading-relaxed overflow-x-auto my-4" dir="ltr"><pre class="m-0"><code><span class="text-rose-400">// &#10007; never do this</span>
Head = Head-&gt;next;</code></pre></div><div class="code-java bg-[#1E1E2E] rounded-xl p-5 shadow-inner border border-gray-800 font-mono text-[13px] text-gray-300 leading-relaxed overflow-x-auto my-4" dir="ltr"><pre class="m-0"><code><span class="text-rose-400">// &#10007; never do this</span>
Head = Head.next;</code></pre></div>$q$, $q$<p>Why not just use <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code> itself? Because <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code> must stay fixed.</p>
         <p>If we changed it &mdash; <code class="code-cpp bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = Head-&gt;next;</code><code class="code-java bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = Head.next;</code> &mdash; Head would now point to node 20, and we'd have lost the first element forever.</p>
         <p>Think of it like your home address. Do you erase it every time you step outside? No &mdash; you leave it fixed, and send a <em>person</em> out walking instead. That person is <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">current</code>.</p>$q$, $q$<p>ليه مش نستخدم Head نفسه؟ لأن Head لازم يفضل ثابت.</p>
         <p>لو غيرناه &mdash; <code class="code-cpp bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = Head-&gt;next;</code><code class="code-java bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head = Head.next;</code> &mdash; بقى Head بيشاور على Node 20. وضاع أول عنصر.</p>
         <p>تخيل عندك عنوان بيتك. هل كل مرة تخرج من البيت تمسح العنوان؟ لا. بتسيبه ثابت، وتستخدم شخص ماشي. وده هو <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">current</code>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (2, 4, $q$Setting it up$q$, $q$الإعداد$q$, $q$A new pointer, starting at Head$q$, $q$اعمل Pointer جديد يبدأ من أول Node$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto">
        
