            <div class="w-16 h-16 text-xl rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d flex-shrink-0">20</div>
        </div><div class="w-8 sm:w-10 h-1 bg-brand-purple relative flex-shrink-0"><div class="absolute right-0 top-1/2 -translate-y-1/2 w-0 h-0 border-y-4 border-y-transparent border-l-[7px] border-l-brand-purple"></div></div><div class="flex flex-col items-center">
